+import type {OptionsInit, PaginateData} from './core/options.js';
+import parseLinkHeader from './core/parse-link-header.js';
+
+/**
+A `pagination.paginate` function that follows the `prev` relation of the `Link` header, for navigating backwards.
+
+It behaves like the default `pagination.paginate`, except that it selects the previous page instead of the next one.
+*/
+export function previousPage<BodyType = unknown, ElementType = unknown>({response}: PaginateData<BodyType, ElementType>): OptionsInit | false {
+	const rawLinkHeader = response.headers.link;
+	if (typeof rawLinkHeader !== 'string' || rawLinkHeader.trim() === '') {
+		return false;
+	}
+
+	const parsed = parseLinkHeader(rawLinkHeader);
+	const previous = parsed.find(entry => entry.parameters.rel === 'prev' || entry.parameters.rel === '"prev"');
+
+	if (previous) {
+		return {
+			url: new URL(previous.reference, response.url),
+		};
+	}
+
+	return false;
+}
diff --git a/test/previous-page.ts b/test/previous-page.ts
new file mode 100644
index 0000000..e0a24b5
--- /dev/null
+++ b/test/previous-page.ts
@@ -0,0 +1,44 @@
+import test from 'ava';
+import {previousPage} from '../source/previous-page.js';
+import type {PaginateData} from '../source/core/options.js';
+
+const createData = (link?: string | string[]) => ({
+	response: {
+		headers: link === undefined ? {} : {link},
+		url: 'https://example.com/items?page=3',
+	},
+	currentItems: [],
+	allItems: [],
+}) as unknown as PaginateData<unknown, unknown>;
+
+test('follows the `prev` relation', t => {
+	const result = previousPage(createData('<https://example.com/items?page=4>; rel="next", <https://example.com/items?page=2>; rel="prev"'));
+	t.deepEqual(result, {url: new URL('https://example.com/items?page=2')});
+});
+
+test('supports the unquoted `prev` relation', t => {
+	const result = previousPage(createData('<https://example.com/items?page=2>; rel=prev'));
+	t.deepEqual(result, {url: new URL('https://example.com/items?page=2')});
+});
+
+test('resolves relative references against the response URL', t => {
+	const result = previousPage(createData('</items?page=2>; rel="prev"'));
+	t.deepEqual(result, {url: new URL('https://example.com/items?page=2')});
+});
+
+test('ignores the `next` relation', t => {
+	t.false(previousPage(createData('<https://example.com/items?page=4>; rel="next"')));
+});
+
+test('returns false when the Link header is missing or empty', t => {
+	t.false(previousPage(createData()));
+	t.false(previousPage(createData('')));
+	t.false(previousPage(createData('   ')));
+	t.false(previousPage(createData(['<https://example.com/items?page=2>; rel="prev"'])));
+});
+
+test('throws on an invalid Link header', t => {
+	t.throws(() => previousPage(createData('https://example.com/items?page=2; rel="prev"')), {
+		message: 'Invalid format of the Link header reference: https://example.com/items?page=2',
+	});
+});
